export const meta = {
  name: 'memory-bench-startup-decisions',
  description: 'Investigate entire-graph PRs #82/#84/#81 + pinned-symbol-ID exposure to decide merge order and schema-bump need',
  phases: [
    { title: 'Find', detail: 'PR84 scope, PR82 live-repro, ID-pin sweep, agentGuide gap' },
    { title: 'Verify', detail: 'adversarial re-sweep of ID-pin conclusion (opus)' },
  ],
}

const SCRATCH = '/private/tmp/claude-501/-Users-suhaan-devenv/27642e0f-a981-4143-aea0-6f4f8cb34d37/scratchpad'
const COMMON = `STYLE: caveman-ultra compressed output. Use rtk-prefixed commands where the hook offers them. Every claim needs file:line or a command+output. NEVER write to /Users/suhaan/devenv/entire-graph or any main checkout — clone fresh under ${SCRATCH}/<yourname>/ if you need a checkout. Do not commit or push anywhere.`

const PR84_SCHEMA = {
  type: 'object', required: ['state','ci','sizeLines','claimedResults','reproducible','pinsSymbolIds','conflictDepth'],
  properties: {
    state: {type:'string', description:'open/merged/closed + mergeable status'},
    ci: {type:'string', description:'CI check status summary'},
    sizeLines: {type:'string', description:'files changed, +/- lines'},
    claimedResults: {type:'string', description:'the prose-memory/LOCOMO numbers the PR claims, with file paths where they live'},
    reproducible: {type:'string', description:'is there a harness/scripts/raw-data in the PR to reproduce the numbers? what exactly'},
    pinsSymbolIds: {type:'string', description:'does PR84 code persist entire-graph symbol IDs anywhere? file:line or NO'},
    conflictDepth: {type:'string', description:'per-file depth of PR84 changes in the 8 conflict files vs #82: internal/sem/{search,provider,search_blocks,search_enclosure,search_verify,search_verify_test}.go, internal/cli/{search.go,help_test.go}'},
    notes: {type:'string'}
  }
}

const PR82_SCHEMA = {
  type: 'object', required: ['state','ci','headCommits','churnAtHead','stableIdVersion','callsEdgeDrop'],
  properties: {
    state: {type:'string'},
    ci: {type:'string'},
    headCommits: {type:'string', description:'latest commits on the head branch, esp any pushed today claiming to fix ID churn'},
    churnAtHead: {type:'string', description:'LIVE RESULT: built the PR-82-head binary, indexed a TS repo with overloads — do implementation symbol IDs gain #sig:<hash> vs a main-built binary on the same repo? paste both IDs'},
    stableIdVersion: {type:'string', description:'what stable_id_version does the head binary report'},
    callsEdgeDrop: {type:'string', description:'LIVE RESULT: in fast profile, are CALLS edges dropped / impact reporting DEGENERATE no-callers on a repo with a real caller?'},
    notes: {type:'string'}
  }
}

const SWEEP_SCHEMA = {
  type: 'object', required: ['storesFound','pinnedIdEvidence','verdict'],
  properties: {
    storesFound: {type:'string', description:'every durable persistence layer found in cmm/, entire-brain/, p0p1/ (tables, fact files, caches) — enumerate'},
    pinnedIdEvidence: {type:'string', description:'file:line for every place an entire-graph symbol ID (repo:Lang:path:kind:name, #sig:, stable_id, compound-v1) is written to durable storage; or NONE'},
    verdict: {type:'string', enum:['PINS_IDS','NO_PINNING','UNCLEAR']},
    notes: {type:'string'}
  }
}

const VERIFY_SCHEMA = {
  type: 'object', required: ['verdict','evidence'],
  properties: {
    verdict: {type:'string', enum:['CONFIRMED','REFUTED','PARTIAL']},
    evidence: {type:'string', description:'file:line for every store checked and what was found; what the first sweep missed, if anything'},
    notes: {type:'string'}
  }
}

const GUIDE_SCHEMA = {
  type: 'object', required: ['pr81Covers','agentGuideGuarded','drift','guardPlan'],
  properties: {
    pr81Covers: {type:'string', description:'what artifact PR81 test actually parses/binds, file:line'},
    agentGuideGuarded: {type:'string', description:'is internal/cli/agents.go const agentGuide covered by any test on main or PR81? file:line'},
    drift: {type:'string', description:'commands/flags agentGuide documents that differ from repo-root AGENTS.md or from real parsers'},
    guardPlan: {type:'string', description:'smallest test that would bind agentGuide to the real parsers — can PR81 machinery be reused? file:line of the machinery'},
    notes: {type:'string'}
  }
}

phase('Find')

const [pr84, pr82, guide, sweep] = await parallel([
  () => agent(`${COMMON}
Inspect entire-graph PR #84 (repo entireio/entire-graph, branch codex/eg-prose-memory-v52-release). Tasks:
1. gh pr view 84 --repo entireio/entire-graph --json state,mergeable,statusCheckRollup,title,body — summarize state+CI.
2. gh pr diff 84 --repo entireio/entire-graph (use --stat first; full diff only for files you must read). Size?
3. The PR ships prose-memory / LOCOMO results. Find the claimed numbers (in the PR body, docs/, bench/ files it adds). What exactly is claimed, where do the result files live, and is there a harness/scripts/raw data in the PR that could reproduce them, or only summary numbers?
4. Does any code/data in this PR persist entire-graph symbol IDs (format repo:Lang:path:kind:name, possibly #sig:<hash> suffix) into a durable store (snapshot files, DB, fact files)? file:line or NO.
5. For the 8 known #82-conflict files (internal/sem/search.go, provider.go, search_blocks.go, search_enclosure.go, search_verify.go, search_verify_test.go, internal/cli/search.go, internal/cli/help_test.go) report how many lines #84 touches in each and whether the changes are mechanical (rename/format) or semantic.`,
    {label:'inspect:PR84', phase:'Find', schema: PR84_SCHEMA, model:'sonnet', effort:'medium'}),

  () => agent(`${COMMON}
Live-verify entire-graph PR #82 (repo entireio/entire-graph, branch claude/graph-retrieval-typescript-jltb4l). The claim under test: at #82's CURRENT head, indexing TypeScript with overloaded/ambient functions makes the IMPLEMENTATION symbol's ID gain a '#sig:<hash>' suffix (ID churn vs main) while stable_id_version still reports 'compound-v1'; and in the fast profile CALLS edges get dropped so 'entire graph impact' reports 'IMPACT DEGENERATE: no callers' falsely. The author said they were pushing a fix today (2026-08-07) — the head may have changed. Tasks:
1. gh pr view 82 --repo entireio/entire-graph --json state,mergeable,statusCheckRollup + list head-branch commits with timestamps (gh pr view 82 --json commits or git log after fetch). Any commit after 2026-08-07T18:00Z claiming to fix ID churn?
2. Clone entireio/entire-graph into ${SCRATCH}/pr82/, fetch pull/82/head, build the binary at that head (find the main package under cmd/). Also build a binary at origin/main.
3. Make a tiny TS repo in ${SCRATCH}/pr82/tsrepo with git init + one commit: src/renderList.ts containing two overload declarations of 'export function renderList' plus the implementation, AND a second file src/caller.ts with a function that calls renderList. Index it with BOTH binaries, list symbols (look at internal/sem or run the CLI's symbols/search commands; discover exact commands via --help). Paste the implementation's ID from main-binary vs pr82-binary. Churn = they differ.
4. Report the stable_id_version each binary reports (capabilities/--json output or wherever it surfaces).
5. With the pr82 binary in fast profile (default), run the impact command on renderList — does it report the caller, or DEGENERATE/no-callers? Paste output.
Return LIVE outputs, not source-reading inferences — build and run.`,
    {label:'live-repro:PR82', phase:'Find', schema: PR82_SCHEMA, model:'sonnet', effort:'high'}),

  () => agent(`${COMMON}
Inspect entire-graph PR #81 (repo entireio/entire-graph, branch feat/agents-md-flag-registry-parity) and the shipped agent guide. Tasks:
1. gh pr diff 81 --repo entireio/entire-graph — what does its test parse and bind to the CLI's real argument parsers? Exactly which artifact (repo-root AGENTS.md? which path)? file:line.
2. Read /Users/suhaan/devenv/entire-graph/internal/cli/agents.go (read-only is fine) — confirm 'const agentGuide' exists, what commands/flags it documents, and whether ANY test on main or in PR81 parses/guards that string. file:line.
3. Diff the CONTENT: does agentGuide document any command, subcommand, or flag that repo-root AGENTS.md does not (or vice versa), and do any of agentGuide's documented commands/flags not exist in the real parsers today? Spot-check against internal/cli command definitions.
4. Propose the smallest guard: can PR81's parity machinery be pointed at the agentGuide const too? Name the functions/files to reuse, file:line.`,
    {label:'inspect:agentGuide', phase:'Find', schema: GUIDE_SCHEMA, model:'sonnet', effort:'medium'}),

  () => agent(`${COMMON}
Sweep for pinned entire-graph symbol IDs in durable memory stores. Context: entire-graph symbol IDs look like 'local/tsrepo:TypeScript:src/renderList.ts:function:renderList' and may gain '#sig:<hash>'; the ID scheme is called 'compound-v1'. An upcoming change churns these IDs. Question: does ANY memory store on this machine persist such IDs durably, so churn would silently invalidate it?
Sweep these trees (read-only): /Users/suhaan/devenv/cmm/ (codebase-memory-mcp), /Users/suhaan/devenv/entire-brain/, /Users/suhaan/devenv/p0p1/ (brain-75, api-242). Method:
1. Enumerate every durable persistence layer first: DB schemas/migrations, fact/JSONL stores, caches that survive across sessions. List them.
2. For each, check whether entire-graph symbol IDs are stored: grep for '#sig:', 'compound-v1', 'stable_id', 'symbol_id', ':function:', ':method:', 'sem symbols', 'sem edges', 'graph search' — and follow any code path where output of the entire CLI / entire-graph is written into the store.
3. Distinguish DURABLE pinning (survives re-index, used as a foreign key later) from EPHEMERAL use (per-session, recomputed each time).
Verdict: PINS_IDS (with file:line), NO_PINNING, or UNCLEAR.`,
    {label:'sweep:pinnedIDs', phase:'Find', schema: SWEEP_SCHEMA, model:'sonnet', effort:'medium'})
    .then(async c1 => {
      const c2 = await agent(`${COMMON}
ADVERSARIAL VERIFICATION. A first sweep concluded: verdict=${c1 ? c1.verdict : 'MISSING'}; evidence: ${c1 ? JSON.stringify(c1.pinnedIdEvidence).slice(0,1500) : 'none'}; stores it found: ${c1 ? JSON.stringify(c1.storesFound).slice(0,1500) : 'none'}.
Your job: assume the first sweep is WRONG until you independently reproduce its conclusion. Question: does any durable memory store under /Users/suhaan/devenv/cmm/, /Users/suhaan/devenv/entire-brain/, or /Users/suhaan/devenv/p0p1/ persist entire-graph symbol IDs (compound-v1 'repo:Lang:path:kind:name', optional '#sig:<hash>')? Use a DIFFERENT modality than grepping for the obvious strings: start from the write paths — find every function that writes to a durable store (SQL INSERT/UPSERT, file append, KV put), trace what data flows into it, and check whether any field originates from entire-graph symbol output ('entire sem symbols/edges', graph search results, provider IDs). Also check actual on-disk artifacts (existing .db/.sqlite/.jsonl fact files) for ID-shaped strings, not just code. Verdict CONFIRMED (first sweep right), REFUTED (it missed pinning — give file:line), or PARTIAL.`,
        {label:'verify:pinnedIDs', phase:'Verify', schema: VERIFY_SCHEMA, model:'opus', effort:'high'})
      return {c1, c2}
    }),
])

return { pr84, pr82, guide, sweep }

export const meta = {
  name: 'memory-comp-landscape',
  description: 'Research memory-tool competitors (mem0, cmm, graphify, cognee, supermemory, letta) + graphmark memory suite mechanics for comp.md',
  phases: [
    { title: 'Research', detail: '6 competitor web-research agents + 1 local graphmark/our-numbers agent' },
    { title: 'Verify', detail: 'source-check headline benchmark claims (opus)' },
  ],
}

const SCRATCH = '/private/tmp/claude-501/-Users-suhaan-devenv/27642e0f-a981-4143-aea0-6f4f8cb34d37/scratchpad'
const COMMON = `STYLE: caveman-ultra compressed output. Use rtk-prefixed commands where offered. Every number needs a source URL or file:line. Read-only on all main checkouts; never commit/push.`

const COMP_SCHEMA = {
  type: 'object', required: ['name','ghUrl','whatItIs','memoryArchitecture','benchmarkClaims','domain'],
  properties: {
    name: {type:'string'},
    ghUrl: {type:'string', description:'canonical GitHub URL'},
    stars: {type:'string', description:'GH stars (approx) + license + last-activity'},
    whatItIs: {type:'string', description:'2-3 sentence what/who/positioning'},
    memoryArchitecture: {type:'string', description:'how memory works: extraction, storage (vector/graph/kv), retrieval, update/consolidation'},
    benchmarkClaims: {type:'string', description:'EVERY benchmark they publish numbers on: bench name, metric, their number, baseline they compare to, source URL. LOCOMO / LongMemEval / DMR / MSC / SWE-bench / anything'},
    domain: {type:'string', description:'conversational memory vs codebase memory vs both'},
    apiOrOss: {type:'string', description:'OSS self-host vs hosted API vs both; pricing model if hosted'},
    notes: {type:'string', description:'known criticisms, benchmark disputes, rebuttals by others'}
  }
}

const LOCAL_SCHEMA = {
  type: 'object', required: ['memorySuiteMechanics','ourNumbers','cmmIdentity','graphifyIdentity'],
  properties: {
    memorySuiteMechanics: {type:'string', description:'how the graphmark memory/prose-memory suite works end to end: where it lives (repo+path), task construction, arms, scoring/judge, gate, n, what LOCOMO variant is used'},
    ourNumbers: {type:'string', description:'every measured OUR-side memory/recall number found locally: prose-memory, LOCOMO, cmm-parity, graphify comparison — with file:line / PR source and n/CI where present'},
    cmmIdentity: {type:'string', description:'what cmm (codebase-memory-mcp) actually is: GH URL from git remote, author, architecture in 2 sentences'},
    graphifyIdentity: {type:'string', description:'what Graphify is: GH URL / site, what it claims (advertised benchmarks), where our parity work stands (entire-graph PRs #77 #83 — why closed?)'},
    notes: {type:'string'}
  }
}

const VERIFY_SCHEMA = {
  type: 'object', required: ['checked','corrections'],
  properties: {
    checked: {type:'string', description:'each headline claim checked: claim -> source says -> VERBATIM/CLOSE/WRONG'},
    corrections: {type:'string', description:'corrected numbers for anything WRONG, with source URL; or NONE'},
    notes: {type:'string'}
  }
}

phase('Research')

const competitors = [
  {key:'mem0', hint:'mem0ai/mem0 — conversational memory layer, published LOCOMO paper claims (vs OpenAI memory, zep etc). Also find the counter-claims: zep/letta rebuttals about their LOCOMO methodology.'},
  {key:'cognee', hint:'topoteretes/cognee — memory/knowledge-graph pipeline (ECL: extract-cognify-load). Find their published eval numbers (HotpotQA? their own benchmark blog).'},
  {key:'supermemory', hint:'supermemoryai/supermemory — memory API/router. Find LongMemEval or other published numbers, latency claims.'},
  {key:'letta', hint:'letta-ai/letta — MemGPT lineage, agent memory OS. DMR/MSC benchmark lineage, Letta Memory Benchmark / terminal-bench claims, LoCoMo position.'},
  {key:'zep', hint:'getzep/zep + getzep/graphiti — temporal knowledge graph memory. Their LOCOMO/DMR/LongMemEval numbers AND their public dispute with mem0 over LOCOMO scoring. Include graphiti as the OSS engine.'},
]

const webAgents = competitors.map(c => () => agent(`${COMMON}
Web-research the AI-memory product '${c.key}'. Hint: ${c.hint}
Use WebSearch + WebFetch (GH repo README, docs site, benchmark blog posts, arxiv). Fill every schema field. benchmarkClaims must be EXHAUSTIVE — every public number with metric definition (e.g. LOCOMO J-score vs BLEU — say which) and source URL. Include rebuttals/disputes in notes.`,
  {label:`web:${c.key}`, phase:'Research', schema: COMP_SCHEMA, model:'sonnet', effort:'medium'}))

const localAgent = () => agent(`${COMMON}
Local investigation, 4 questions. Look in: /Users/suhaan/graphmark-bench (harness), /Users/suhaan/devenv/graph-bench-results/ (TokensNotes.md, MemoryNotes.md), /Users/suhaan/devenv/cmm/, entire-graph GH PRs #84 #83 #77 (gh pr view/diff --repo entireio/entire-graph), entirehq/graphmark repo (gh + any local clone, e.g. /Users/suhaan/devenv/graphmark* or inside graphmark-bench).
1. MEMORY SUITE MECHANICS: how does the graphmark memory / prose-memory / LOCOMO suite work end to end? Find the suite definition (task set, how memories are seeded, what the agent must recall, arms, judge/scoring code, gate, n). Cite file:line. PR #84 (branch codex/eg-prose-memory-v52-release) ships its results — read the PR diff for the harness+docs it adds.
2. OUR NUMBERS: every our-side measured memory/recall number: prose-memory results, LOCOMO results, cmm-parity comparisons (TokensNotes has a Beat-CMM section), Graphify comparison numbers (PR #83 'verified Graphify native-memory comparison' — read it even though CLOSED, and say WHY it was closed; also PR #77). n + CI where available.
3. CMM IDENTITY: git -C /Users/suhaan/devenv/cmm remote -v → GH URL; README → what it is, architecture in 2 sentences.
4. GRAPHIFY IDENTITY: what is Graphify (GH/site URL — check graphmark docs, entire-graph PR #77/#83 text, /Users/suhaan/devenv/graphify-parity-* artifacts), what benchmarks does it advertise, and where does our parity work stand?`,
  {label:'local:graphmark+ours', phase:'Research', schema: LOCAL_SCHEMA, model:'sonnet', effort:'high'})

const [mem0, cognee, supermemory, letta, zep, local] = await parallel([...webAgents, localAgent])

phase('Verify')

const comps = [mem0, cognee, supermemory, letta, zep].filter(Boolean)
const claimsBlob = comps.map(c => `${c.name}: ${String(c.benchmarkClaims).slice(0,900)}`).join('\n---\n')

const verify = await agent(`${COMMON}
SOURCE-CHECK these competitor benchmark claims before they go into a comparison doc. For each distinct headline number below, WebFetch the cited source (or find the primary source) and verify the number, metric, and comparison baseline are stated correctly. Default to WRONG unless the source clearly supports it. Flag numbers that are self-reported by the vendor vs independently measured, and any metric mislabeling (e.g. quoting a J-score as accuracy).
CLAIMS:\n${claimsBlob}`,
  {label:'verify:claims', phase:'Verify', schema: VERIFY_SCHEMA, model:'opus', effort:'high'})

return { mem0, cognee, supermemory, letta, zep, local, verify }

export const meta = {
  name: 'v52-offline-rederivation',
  description: 'Re-derive PR #84 v52 memory headline numbers from the local raw bundle — zero API spend',
  phases: [
    { title: 'Inventory', detail: 'map the bundle files/schemas/counts' },
    { title: 'Recompute', detail: 'independent recomputation of all headline numbers (opus)' },
    { title: 'Integrity', detail: 'blinding/gate/frozen-commit/drift checks (opus)' },
  ],
}

const BUNDLE = '/Users/suhaan/devenv/graphify-parity-artifacts/advertised-memory-native-v52'
const HARNESS = '/Users/suhaan/devenv-worktrees/graphify-parity-prose-v52/graphify-parity'
const COMMON = `STYLE: caveman-ultra compressed output. Use rtk where offered. Every number needs a command+output or file:line. READ-ONLY everywhere — no writes outside the scratchpad /private/tmp/claude-501/-Users-suhaan-devenv/27642e0f-a981-4143-aea0-6f4f8cb34d37/scratchpad/v52verify/. No API/model calls, no network — this is offline recomputation.`

const INV_SCHEMA = { type:'object', required:['fileMap','rawSchemas','counts'], properties:{
  fileMap:{type:'string', description:'every file in the bundle w/ size and role (raw cells, grades, audit, manifests, config)'},
  rawSchemas:{type:'string', description:'schema of each raw JSONL/JSON: field names + one sample row (truncated), esp. per-cell grade rows, recall rows, opus-audit rows'},
  counts:{type:'string', description:'row counts per file, split by arm and by benchmark; where the 3150 and 630 live'},
  notes:{type:'string'} } }

const RECOMP_SCHEMA = { type:'object', required:['perNumber','overall'], properties:{
  perNumber:{type:'string', description:'for EACH claimed number: claimed vs recomputed vs verdict CONFIRMED/REFUTED/UNDERIVABLE + exact command/script used. Numbers: LOCOMO recall@10 0.9143/0.7866/0.0; LOCOMO QA 77.22/59.33/22.33; LME-S QA 76.0/68.0/6.0; paired delta +0.1648 CI [+0.1034,+0.2146] McNemar p=1.70e-11; audit agreement 98.41% kappa 0.9682'},
  overall:{type:'string', enum:['ALL_CONFIRMED','PARTIAL','REFUTED']},
  discrepancies:{type:'string'}, notes:{type:'string'} } }

const INTEG_SCHEMA = { type:'object', required:['checks','verdict'], properties:{
  checks:{type:'string', description:'each check: PASS/FAIL + evidence'},
  verdict:{type:'string', enum:['CLEAN','ISSUES_FOUND']},
  issues:{type:'string'}, notes:{type:'string'} } }

phase('Inventory')
const inv = await agent(`${COMMON}
Inventory the v52 memory result bundle at ${BUNDLE} (recurse; also scoring/ subdir). Also read ${BUNDLE}/config.json (frozen commits) and note where raw per-cell grades, recall rows, and opus-audit rows live, with schemas + counts per arm/benchmark. Harness source (read-only reference): ${HARNESS}/graphify_parity/{memory_table_scoring.py,grading.py,statistics.py}.`,
  {label:'inventory', phase:'Inventory', schema: INV_SCHEMA, model:'sonnet', effort:'medium'})

phase('Recompute')
const invBlob = JSON.stringify(inv).slice(0, 6000)
const [recomp, integ] = await parallel([
  () => agent(`${COMMON}
INDEPENDENT RECOMPUTATION — default every claimed number to REFUTED until your own arithmetic reproduces it from RAW rows (never from score-summary.json; that is the artifact under test). Bundle: ${BUNDLE}. Inventory from a prior agent: ${invBlob}
Recompute with your own python scripts (write them under the scratchpad):
1. Per-arm LOCOMO n=300 recall@10 and QA accuracy; LongMemEval-S n=50 QA accuracy — from raw per-cell rows, checking the denominator handling (3 reps: how are reps aggregated? majority? mean? reproduce the bundle's documented aggregation from ${HARNESS}/graphify_parity/memory_table_scoring.py and say which).
2. Paired Entire−Graphify accuracy delta over the 350 paired cases + cluster bootstrap 95% CI (cluster = case, resample cases, 10k iters) + McNemar exact/approx p.
3. Opus-audit agreement % and Cohen's kappa over the 630 audit cells vs primary grades.
Compare each to the claimed values in the schema description. Report per-number verdicts.`,
    {label:'recompute', phase:'Recompute', schema: RECOMP_SCHEMA, model:'opus', effort:'high'}),
  () => agent(`${COMMON}
HARNESS-INTEGRITY CHECKS on the v52 bundle ${BUNDLE} + harness ${HARNESS}. Default each to FAIL until evidence shows otherwise:
1. BLINDING: identity_vocabulary_sha256 in score-summary — find the vocabulary, then grep RAW candidate answers fed to the judge for tool-identity strings (entire/graphify/cmm/graph names). Any leak = FAIL.
2. GATE SYMMETRY: how were invalid/retried attempts handled per arm (promotion-summary says 0 invalid / 7 retried) — check retries were arm-symmetric in policy and the 7 retried cells' arms; check no arm's failures were silently dropped (per-arm denominators equal).
3. FROZEN COMMITS: config.json entire_stable/entire_candidate/graphify/cmm commits — verify each SHA exists in the corresponding local clone (${HARNESS}, /Users/suhaan/devenv/graphify-parity-inputs/{graphify,codebase-memory-mcp}) and matches what PR #84 text claims (product commit c9641bf1...).
4. ARMS DRIFT: arms.py GRAPH_ARMS=(graphify,entire-stable,entire-candidate) vs score-summary memory_arms=[graphify,entire-candidate,codebase-memory-mcp] — find the actual invocation config that produced the run (config.json / workflows.py) and explain the drift: was cmm run under the same phase gate as the others?
5. SAMPLE SEAL: memory-samples.json frozen subsample — confirm the 300+50 cases scored are exactly the sealed sample (IDs match), and disjoint from any tune-phase cases.
6. PROMPT SYMMETRY: reader/judge prompts identical across arms (grading.py paths + any per-arm prompt material in the bundle).`,
    {label:'integrity', phase:'Integrity', schema: INTEG_SCHEMA, model:'opus', effort:'high'}),
])

return { inv, recomp, integ }

export const meta = {
  name: 'field-run-staging',
  description: 'Provision graphbench-e/f, prep all 3 VMs, verify keys + Fireworks rate card, retest supermemory self-host — no paid run, no code deploy yet',
  phases: [
    { title: 'Provision', detail: 'create e/f VMs, recon c, keys+rates' },
    { title: 'Stage', detail: 'per-VM service stacks + supermemory retest' },
  ],
}

const SCRATCH = '/private/tmp/claude-501/-Users-suhaan-devenv/27642e0f-a981-4143-aea0-6f4f8cb34d37/scratchpad'
const COMMON = `STYLE: caveman-ultra compressed output. Evidence = command+output. GCP project graph-benchmarks-504800, zone us-east1-b, gcloud is authed as suhaan@entire.io.
HARD RULES: NO paid benchmark phases, NO harness runs, NO code deploy of the memarms branch (a rebase agent is still rewriting it). NEVER touch graphbench-a or graphbench-b (another agent's live benchmarks run there). Never overwrite any file a running process may hold open — write to a temp path then atomic mv. Do not print secret values — report only env-var NAMES, file paths, and yes/no presence. Local writes only under ${SCRATCH}.`

const PROVISION_SCHEMA = { type:'object', required:['status','detail'], properties:{
  status:{type:'string', enum:['READY','PARTIAL','FAILED']},
  detail:{type:'string'}, notes:{type:'string'} } }

const KEYS_SCHEMA = { type:'object', required:['fireworksKey','anthropicKey','rateCard','extractionPick','limits'], properties:{
  fireworksKey:{type:'string', description:'how the v52 harness sources it (env name/path, file:line) + present? + live-auth ping result (ONE minimal completion allowed, <$0.01)'},
  anthropicKey:{type:'string', description:'env name/path + present? presence only, NO call'},
  rateCard:{type:'string', description:'current Fireworks $/Mtok for kimi-k3 AND 3-4 cheap extraction candidates, with source URL + date'},
  extractionPick:{type:'string', description:'recommended extraction model + why + recomputed LoCoMo+LME-S 5-arm ingestion USD at its real rates (scale RUN-PLAN scripts)'},
  limits:{type:'string', description:'TPM/RPM limits of our Fireworks account if discoverable; else UNKNOWN + how preflight will measure'},
  notes:{type:'string'} } }

phase('Provision')

const [vms, crecon, keys] = await parallel([
  () => agent(`${COMMON}
