let agreed = false
const log = []
while (round < 4 && !agreed) {
  round++
  const v = await agent(`${COMMON}
ROUND ${round} — ADVERSARIAL VERIFY of ${DOC}. Read the whole doc. Default EVERY "VERIFIED"/"PARTIAL"/"REFUTED" verdict to WRONG until you independently reproduce its evidence — re-run the count (gq=0 sessions), re-open the immutable-js payload on graphbench-c and confirm gold rank-1 + RELATED SITES strictly-below, re-check the 10.1%/73-726 precision, re-confirm each §-citation in TokensNotes actually says what the doc claims, and check no struck idea (§2) is being re-proposed as live. Also check the honest-headline (§0) isn't overclaiming a token win anywhere. Return challenges (empty list + agree:true ONLY if nothing survives). Be specific: quote the doc claim, give your contradicting evidence, name the fix.`,
    {label:`verify:r${round}`, phase:'Consensus', schema: VERIFY_SCHEMA, model:'opus', effort:'high'})
  log.push({round, agree: v?.agree, nChallenges: v?.challenges?.length || 0})
  if (v?.agree && (!v.challenges || v.challenges.length === 0)) { agreed = true; break }
  const blob = JSON.stringify(v?.challenges || []).slice(0, 8000)
  const m = await agent(`${COMMON}
ROUND ${round} — MAKER revise ${DOC}. The verifier raised these challenges:\n${blob}\nFor EACH: either FIX the doc (use Edit on ${DOC} — apply the correction faithfully, keep the doctrine, never inflate a token claim) OR REBUT it with harder evidence (a number/file:line/replay the verifier missed) and leave that part as-is. You MUST Edit the file for every accepted fix. Do not weaken correct honest verdicts to appease a wrong challenge — rebut those. Report resolved[] with FIXED/REBUTTED per challenge.`,
    {label:`maker:r${round}`, phase:'Consensus', schema: MAKER_SCHEMA, model:'opus', effort:'high'})
  log.push({round, makerResolved: m?.resolved?.length || 0, docUpdated: m?.docUpdated})
}

// final clean-verify pass to record the consensus state
const final = await agent(`${COMMON}
FINAL PASS on ${DOC}: confirm the maker↔verifier loop converged. Read the doc, verify every remaining VERIFIED claim reproduces, and append a short "Consensus log" entry at the very end of the file (Edit) recording: rounds run, whether agreement was reached, and any claim that remains DISPUTED (if the loop hit the round cap without full agreement, list the open items honestly rather than papering over them). Return a 3-line summary.`,
  {label:'final', phase:'Consensus', schema:{type:'object', required:['converged','summary'], properties:{converged:{type:'boolean'}, disputed:{type:'string'}, summary:{type:'string'}}}, model:'opus', effort:'high'})

return { rounds: round, agreed, log, final }

