    def _parse_corpus(self, corpus: Path) -> tuple[list[dict[str, Any]], list[str]]:
        """Read the materialized sessions into ordered (path, line, speaker, text)."""
        messages: list[dict[str, Any]] = []
        speakers: list[str] = []
        for session_file in sorted(corpus.glob("*.md")):
            text = session_file.read_text(encoding="utf-8", errors="replace")
            for number, raw in enumerate(text.splitlines(), start=1):
                matched = _MESSAGE_LINE.match(raw)
                if not matched:
                    continue
                speaker = matched.group("speaker").strip()
                content = matched.group("text").strip()
                if not speaker or not content:
                    continue
                if speaker not in speakers:
                    speakers.append(speaker)
                messages.append(
                    {
                        "path": session_file.name,
                        "line": number,
                        "speaker": speaker,
                        "text": content,
                    }
                )
        return messages, speakers
