try:
    d = json.load(open(f))
except Exception:
    raise SystemExit
m = d.get("metadata", {}) or {}
mc = d.get("metrics_by_cutoff", {}) or {}
k = "top_200" if "top_200" in mc else (next(iter(mc), None))
o = (mc.get(k, {}) or {}).get("overall", {}) if k else {}
tot = o.get("total") or 0
