    raise SystemExit
acc = o.get("accuracy") or 0.0
cats = []
for c, s in sorted(((mc.get(k, {}) or {}).get("by_category", {}) or {}).items()):
    if isinstance(s, dict):
        cats.append("%s %.1f(n=%d)" % (c, s.get("accuracy", 0.0), s.get("total", 0)))
print("- [%s] **%s**: %.2f%% (%s/%s) | %s | file=%s"
      % (m.get("timestamp", ""), m.get("project_name"), acc,
         o.get("correct"), tot, " ".join(cats), os.path.basename(f)))

