import json,glob,os
def cats(d):
    fs=[f for f in glob.glob(os.path.join(d,"*.json")) if all(k not in f for k in ("_ingestion","_progress","_abs"))]
    agg={}
    for f in fs:
        try: j=json.load(open(f))
        except Exception: continue
        r=(j.get("cutoff_results",{}) or {}).get("top_200",{}) or {}
        if "judgment" not in r: continue
        c=j.get("category_name") or str(j.get("category"))
        a=agg.setdefault(c,[0,0]); a[1]+=1; a[0]+= 1 if r["judgment"]=="CORRECT" else 0
    return agg
R="results/locomo"
for name,d in [("sw_eg_tsmr (turn+session + PR100)",f"{R}/predicted_sw_eg_tsmr")]:
    a=cats(d); tot=sum(v[1] for v in a.values()); cor=sum(v[0] for v in a.values())
    print("%s  n=%d  overall=%.2f"%(name,tot,100*cor/tot if tot else 0))
    for k in sorted(a): print("   %-14s %6.2f  (%d/%d)"%(k,100*a[k][0]/a[k][1],a[k][0],a[k][1]))
PY' 2>&1 | tail -10
